        pIn = pIn.offset(4 as c_int as isize);
        pMatch = pMatch.offset(4 as c_int as isize);
    }
    if pIn < pInLimit.offset(-(1 as c_int as isize))
        && LZ4_read16(pMatch as *const c_void) as c_int
