        pIn = pIn.offset(2 as c_int as isize);
        pMatch = pMatch.offset(2 as c_int as isize);
    }
    if pIn < pInLimit && *pMatch as c_int == *pIn as c_int {
        pIn = pIn.offset(1);
    }
    return pIn.offset_from(pStart) as c_long as c_uint;
